<script>const cfg=<?=json_encode($config,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const token=localStorage.getItem('admin_token')||sessionStorage.getItem('admin_token')||'';const clear=()=>{localStorage.removeItem('admin_token');sessionStorage.removeItem('admin_token');};const login=()=>location.replace(cfg.loginUrl);const esc=v=>String(v??'-').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function start(){if(!token)return login();try{const guard=await fetch(cfg.apiDashboardUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/json'}});if(!guard.ok){clear();return login();}const guardData=await guard.json();const section=<?=json_encode($key)?>;if(section==='profil'){const a=guardData.auth||{};document.getElementById('resourceHead').innerHTML='<tr><th>Informasi</th><th>Detail</th></tr>';document.getElementById('resourceRows').innerHTML='<tr><td>Username</td><td>'+esc(a.username||'-')+'</td></tr><tr><td>ID Admin</td><td>'+esc(a.id||a.sub||'-')+'</td></tr><tr><td>Role</td><td>'+esc(a.role||'admin')+'</td></tr>';document.getElementById('resourceMessage').textContent='Profil admin yang sedang login.';return;}if(section==='fasilitas'){setupFacilities();await loadFacilities();return;}const res=await fetch(cfg.apiUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/json'}});const json=await res.json();if(!res.ok)throw new Error(json.message||'Gagal memuat data.');const rows=Array.isArray(json.data)?json.data:(json.data?[json.data]:[]);if(section==='kategori'){const categoryPhoto=name=>{const n=String(name||'').toLocaleLowerCase('id-ID');if(n.includes('alam')||n.includes('gunung'))return '../assets/images/telaga.png?v=20261112-exact';if(n.includes('air')||n.includes('curug')||n.includes('air terjun'))return '../assets/images/kategori-air-curug.jpeg?v=20261112-exact';if(n.includes('buatan')||n.includes('kuliner'))return '../assets/images/kategori-buatan-kuliner.jpeg?v=20261112-exact';if(n.includes('sejarah')||n.includes('budaya'))return '../assets/images/kategori-sejarah-budaya.jpeg?v=20261112-exact';return '../assets/images/img.png';};document.getElementById('resourceHead').innerHTML='<tr><th>No</th><th>Foto</th><th>Kategori</th><th>Jumlah Wisata</th></tr>';document.getElementById('resourceRows').innerHTML=rows.length?rows.map((r,i)=>'<tr><td class="kategori-number" data-label="No">'+(i+1)+'</td><td class="kategori-photo" data-label="Foto"><img src="'+categoryPhoto(r.name)+'" alt="Foto '+esc(r.name)+'" loading="lazy"></td><td class="kategori-name" data-label="Kategori">'+esc(r.name)+'</td><td class="kategori-total" data-label="Jumlah wisata">'+esc(r.total_destinations??0)+'</td></tr>').join(''):'<tr><td colspan="4" class="text-center py-4">Belum ada data kategori.</td></tr>';document.getElementById('resourceMessage').textContent='Data berhasil dimuat ('+rows.length+' kategori).';}else{let cols=section==='fasilitas'?['id','name','icon_code','description']:section==='pengguna'?['id','nama','email','no_telepon']:['id_ulasan','nama_pengguna','nama_wisata','rating','komentar','tanggal_ulasan'];document.getElementById('resourceHead').innerHTML='<tr>'+cols.map(c=>'<th>'+esc(c.replaceAll('_',' '))+'</th>').join('')+'</tr>';document.getElementById('resourceRows').innerHTML=rows.length?rows.map(r=>'<tr>'+cols.map(c=>'<td>'+esc(r[c])+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+cols.length+'" class="text-center py-4">Belum ada data.</td></tr>';document.getElementById('resourceMessage').textContent='Data berhasil dimuat ('+rows.length+' data).';}}catch(e){document.getElementById('resourceMessage').textContent=e.message||'Terjadi kesalahan.';}}
const facilityModal=document.getElementById('facilityModal');
function facilityStatus(message,isError=false){const el=document.getElementById('resourceMessage');if(el){el.textContent=message;el.classList.toggle('is-error',isError);}}
async function facilityRequest(url=cfg.apiUrl,options={}){const headers={Authorization:'Bearer '+token,Accept:'application/json',...(options.headers||{})};if(options.body)headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok)throw new Error(payload.message||'Permintaan fasilitas gagal diproses.');return payload;}
function facilityModalOpen(item=null){const form=document.getElementById('facilityForm');form.reset();document.getElementById('facilityFormError').textContent='';document.getElementById('facilityModalTitle').textContent=item?'Edit Fasilitas':'Tambah Fasilitas';form.dataset.facilityId=item?String(item.id):'';document.getElementById('facilityName').value=item?.name||'';document.getElementById('facilityIcon').value=item?.icon_code||'';document.getElementById('facilityDescription').value=item?.description||'';if(facilityModal){facilityModal.classList.add('is-open');facilityModal.setAttribute('aria-hidden','false');document.body.classList.add('facility-modal-open');document.getElementById('facilityName').focus();}}
function facilityModalClose(){if(facilityModal){facilityModal.classList.remove('is-open');facilityModal.setAttribute('aria-hidden','true');document.body.classList.remove('facility-modal-open');}}
function setupFacilities(){const addBtn=document.getElementById('addFacilityButton');if(addBtn)addBtn.addEventListener('click',()=>facilityModalOpen());if(facilityModal){facilityModal.querySelectorAll('[data-close-facility-modal]').forEach(el=>el.addEventListener('click',facilityModalClose));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&facilityModal.classList.contains('is-open'))facilityModalClose();});}const rows=document.getElementById('resourceRows');if(rows){rows.addEventListener('click',async event=>{const button=event.target.closest('[data-facility-action]');if(!button)return;const id=button.dataset.id;try{if(button.dataset.facilityAction==='edit'){const result=await facilityRequest(cfg.apiUrl+'/'+encodeURIComponent(id));facilityModalOpen(result.data||{});}else if(button.dataset.facilityAction==='delete'){const row=facilitiesCache.find(item=>String(item.id)===String(id));if(!window.confirm('Hapus fasilitas '+(row?.name||'ini')+'?'))return;button.disabled=true;const result=await facilityRequest(cfg.apiUrl+'/'+encodeURIComponent(id),{method:'DELETE'});facilityStatus(result.message||'Fasilitas berhasil dihapus.');await loadFacilities(false);}}catch(error){facilityStatus(error.message,true);button.disabled=false;}});}const form=document.getElementById('facilityForm');if(form)form.addEventListener('submit',saveFacility);}
let facilitiesCache=[];let facilityPage=1;const facilityPageSize=5;
function facilityIconMarkup(item){const supplied=Array.isArray(item.icons)?item.icons:(Array.isArray(item.icon_codes)?item.icon_codes:(item.icon_code?[item.icon_code]:[]));const icons=supplied.flatMap(v=>String(v??'').split(/[;,|]/)).map(v=>v.trim()).filter(Boolean).slice(0,8);if(!icons.length)return '<span class="facility-icon-placeholder">—</span>';const aliases={'camera':'bi-camera-fill','kamera':'bi-camera-fill','fa-camera':'bi-camera-fill','masjid':'bi-house-fill','mushola':'bi-house-fill','toilet':'bi-gender-ambiguous','restroom':'bi-gender-ambiguous','fa-restroom':'bi-gender-ambiguous','parking':'bi-car-front-fill','parkir':'bi-car-front-fill','fa-parking':'bi-car-front-fill','wifi':'bi-wifi','internet':'bi-wifi'};return '<div class="facility-icon-list">'+icons.map(code=>{const key=code.toLocaleLowerCase('id-ID');const safe=aliases[key]||(code.match(/^(?:bi\s+)?bi-[a-z0-9-]+$/)?code.replace(/^bi\s+/,''):(/^bi-[a-z0-9-]+$/.test(code)?code:''));return safe?'<span class="facility-icon-chip" title="'+esc(code)+'"><i class="bi '+esc(safe)+'"></i></span>':'<span class="facility-icon-chip facility-icon-text" title="'+esc(code)+'">'+esc(code.slice(0,3))+'</span>';}).join('')+'</div>'; }
function renderFacilityTable(){const total=facilitiesCache.length;const pages=Math.max(1,Math.ceil(total/facilityPageSize));facilityPage=Math.min(facilityPage,pages);const start=(facilityPage-1)*facilityPageSize;const shown=facilitiesCache.slice(start,start+facilityPageSize);document.getElementById('resourceHead').innerHTML='<tr><th>No</th><th>Ikon</th><th>Nama Fasilitas</th><th>Keterangan</th><th>Aksi</th></tr>';document.getElementById('resourceRows').innerHTML=shown.length?shown.map((item,index)=>{const name=item.facility_name||item.nama_fasilitas||item.name||'-';const description=item.description||item.keterangan||'-';return '<tr><td data-label="No" class="facility-number">'+(start+index+1)+'</td><td data-label="Ikon" class="facility-icons-cell">'+facilityIconMarkup(item)+'</td><td data-label="Nama Fasilitas" class="facility-name">'+esc(name)+'</td><td data-label="Keterangan" class="facility-description">'+esc(description)+'</td><td data-label="Aksi" class="facility-actions"><button type="button" class="facility-action-button is-edit" data-facility-action="edit" data-id="'+esc(item.id)+'" aria-label="Edit '+esc(name)+'"><i class="bi bi-pencil-square"></i></button><button type="button" class="facility-action-button is-delete" data-facility-action="delete" data-id="'+esc(item.id)+'" aria-label="Hapus '+esc(name)+'"><i class="bi bi-trash-fill"></i></button></td></tr>';}).join(''):'<tr><td colspan="5" class="facility-empty">Belum ada data fasilitas. Klik Tambah Fasilitas untuk membuat data pertama.</td></tr>';const rangeEl=document.getElementById('facilityRange');if(rangeEl)rangeEl.textContent=total?'Menampilkan '+(start+1)+'-'+Math.min(start+facilityPageSize,total)+' dari '+total+' data fasilitas':'Menampilkan 0-0 dari 0 data fasilitas';const nav=document.getElementById('facilityPagination');if(nav){nav.innerHTML='';if(pages>1){const make=(label,page,disabled=false,active=false)=>{const b=document.createElement('button');b.type='button';b.className='facility-page-button'+(active?' is-active':'');b.innerHTML=label;b.disabled=disabled;b.setAttribute('aria-label',typeof label==='string'?label:'Halaman '+page);b.addEventListener('click',()=>{facilityPage=page;renderFacilityTable();});nav.appendChild(b);};make('<i class="bi bi-chevron-left"></i>',Math.max(1,facilityPage-1),facilityPage===1);for(let p=1;p<=pages;p++){if(pages>5&&p>2&&p<pages-1&&Math.abs(p-facilityPage)>1){if(p===3||p===pages-2){const dots=document.createElement('span');dots.className='facility-page-dots';dots.textContent='...';nav.appendChild(dots);}continue;}make(String(p),p,false,p===facilityPage);}make('<i class="bi bi-chevron-right"></i>',Math.min(pages,facilityPage+1),facilityPage===pages);}}}
async function loadFacilities(showLoading=true){if(showLoading)facilityStatus('Memuat data fasilitas...');try{const result=await facilityRequest();facilitiesCache=Array.isArray(result.data)?result.data:[];facilityPage=1;renderFacilityTable();facilityStatus('Data berhasil dimuat ('+facilitiesCache.length+' fasilitas).');}catch(error){facilityStatus(error.message,true);document.getElementById('resourceHead').innerHTML='';document.getElementById('resourceRows').innerHTML='<tr><td colspan="5" class="facility-empty">Data fasilitas gagal dimuat. Periksa koneksi API dan migrasi database.</td></tr>';const rangeEl=document.getElementById('facilityRange');if(rangeEl)rangeEl.textContent='';const nav=document.getElementById('facilityPagination');if(nav)nav.innerHTML='';}}
async function saveFacility(event){event.preventDefault();const form=event.currentTarget;const id=form.dataset.facilityId;const payload={name:document.getElementById('facilityName').value.trim(),icon_code:document.getElementById('facilityIcon').value.trim(),description:document.getElementById('facilityDescription').value.trim()};const errorBox=document.getElementById('facilityFormError');const saveButton=document.getElementById('saveFacilityButton');errorBox.textContent='';if(!payload.name){errorBox.textContent='Nama fasilitas wajib diisi.';return;}saveButton.disabled=true;saveButton.textContent='Menyimpan...';try{const result=await facilityRequest(id?cfg.apiUrl+'/'+encodeURIComponent(id):cfg.apiUrl,{method:id?'PUT':'POST',body:JSON.stringify(payload)});facilityModalClose();facilityStatus(result.message||'Data fasilitas berhasil disimpan.');await loadFacilities(false);}catch(error){errorBox.textContent=error.message;}finally{saveButton.disabled=false;saveButton.textContent='Simpan';}}
async function logout(){try{await fetch(cfg.apiLogoutUrl,{method:'POST',headers:{Authorization:'Bearer '+token}});}finally{clear();login();}}document.getElementById('logoutButton').onclick=logout;document.getElementById('mobileLogoutButton').onclick=logout;document.getElementById('sidebarCollapse').onclick=()=>document.body.classList.toggle('sidebar-collapsed');document.getElementById('mobileMenuButton').onclick=()=>document.body.classList.toggle('mobile-sidebar-open');document.getElementById('sidebarBackdrop').onclick=()=>document.body.classList.remove('mobile-sidebar-open');start();</script></body></html>
